window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-063dba3365655ab2"]={"versions": [{"id": "FIG-063dba3365655ab2", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (BSW Module Description / EcucModuleDef) für das BSW-Modul <code>MemAcc</code> (Memory Access) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die statische Konfigurationsstruktur, Containerhierarchien und Parameterdefinitionen des Moduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Wurzelelement ist das Modul <code>MemAcc: EcucModuleDef</code> (Multiplizität 0..1). Es aggregiert über die Kompositionsrolle <code>+container</code> zwei Konfigurationscontainer:</p>\n<ul class=\"fig-list\"><li><code>MemAccGeneral: EcucParamConfContainerDef</code> (Multiplizität 1..1), aggregiert über <code>+parameter</code> fünf Konfigurationsparameter:\n<ul class=\"fig-list\"><li><code>MemAccMainFunctionPeriod: EcucFloatParamDef</code> (Multiplizität 1..1, <code>min = 0.0001</code>, <code>max = 1.0</code>, <code>defaultValue = 0.005</code>)\n</li><li><code>MemAccDevErrorDetect: EcucBooleanParamDef</code> (Multiplizität 1..1)\n</li><li><code>MemAccCompareApi: EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>)\n</li><li><code>MemAccUseMemFuncPtrTable: EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = true</code>)\n</li><li><code>MemAcc64BitSupport: EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>)\n</li></ul>\n</li><li><code>MemAccAddressAreaConfiguration: EcucParamConfContainerDef</code> (Multiplizität 1..65535) als Sammelelement für logische Speicheradressbereiche.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell stellt das Diagramm keine Laufzeitinteraktionen, Zustandsübergänge oder Aufrufsequenzen dar. Es definiert die Eingangsdaten für Generatoren zur Erzeugung von Konfigurationsheadern und Datenstrukturen zur Compile- bzw. Initialisierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für Generatoren und Konfigurationswerkzeuge (ECU Configuration Tool) des Moduls MemAcc. Das Modul muss genau einmal bzw. gar nicht im System vorhanden sein. <code>MemAccGeneral</code> ist obligatorisch. <code>MemAccAddressAreaConfiguration</code> erzwingt mindestens einen Adressbereich (maximal 65535). Parameter ohne Standardwerte wie <code>MemAccDevErrorDetect</code> müssen explizit konfiguriert werden; Boolesche Flags steuern die Codegenerierung für Funktionspointertabellen, 64-Bit-Adressierung sowie die Bereitstellung der Compare-API.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7b29f334902e1f63", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (BSW Module Description / EcucModuleDef) für das BSW-Modul <code>MemAcc</code> (Memory Access) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die statische Konfigurationsstruktur, Containerhierarchien und Parameterdefinitionen des Moduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Wurzelelement ist das Modul <code>MemAcc: EcucModuleDef</code> (Multiplizität 0..1). Es aggregiert über die Kompositionsrolle <code>+container</code> zwei Konfigurationscontainer:</p>\n<ul class=\"fig-list\"><li><code>MemAccGeneral: EcucParamConfContainerDef</code> (Multiplizität 1..1), aggregiert über <code>+parameter</code> sechs Konfigurationsparameter:\n<ul class=\"fig-list\"><li><code>MemAccMainFunctionPeriod: EcucFloatParamDef</code> (Multiplizität 1..1, <code>min = 0.0001</code>, <code>max = 1.0</code>, <code>defaultValue = 0.005</code>)\n</li><li><code>MemAccDevErrorDetect: EcucBooleanParamDef</code> (Multiplizität 1..1)\n</li><li><code>MemAccCompareApi: EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>)\n</li><li><code>MemAccUseMemFuncPtrTable: EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = true</code>)\n</li><li><code>MemAcc64BitSupport: EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>)\n</li><li><code>MemAccPublicCddHeaderFile: EcucStringParamDef</code> (Multiplizität 0..*, <code>maxLength = 32</code>, <code>minLength = 1</code>)\n</li></ul>\n</li><li><code>MemAccAddressAreaConfiguration: EcucParamConfContainerDef</code> (Multiplizität 1..65535) als Sammelelement für logische Speicheradressbereiche.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell stellt das Diagramm keine Laufzeitinteraktionen, Zustandsübergänge oder Aufrufsequenzen dar. Es definiert die Eingangsdaten für Generatoren zur Erzeugung von Konfigurationsheadern und Datenstrukturen zur Compile- bzw. Initialisierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Vorgabe für Generatoren und Konfigurationswerkzeuge (ECU Configuration Tool) des Moduls MemAcc. Das Modul muss genau einmal bzw. gar nicht im System vorhanden sein. <code>MemAccGeneral</code> ist obligatorisch. <code>MemAccAddressAreaConfiguration</code> erzwingt mindestens einen Adressbereich (maximal 65535). Parameter ohne Standardwerte wie <code>MemAccDevErrorDetect</code> müssen explizit konfiguriert werden; Boolesche Flags steuern die Codegenerierung für Funktionspointertabellen, 64-Bit-Adressierung sowie die Compare-API. <code>MemAccPublicCddHeaderFile</code> erlaubt die Angabe von bis zu beliebig vielen Header-Dateien (je 1 bis 32 Zeichen) zur Einbindung von Complex Device Drivern.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4c58c90e60b01ed9", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (BSW Module Description / EcucModuleDef) für das BSW-Modul <code>MemAcc</code> (Memory Access) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die statische Konfigurationsstruktur, Containerhierarchien und Parameterdefinitionen des Moduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Wurzelelement ist das Modul <code>MemAcc: EcucModuleDef</code> (Multiplizität 0..1). Es aggregiert über die Kompositionsrolle <code>+container</code> drei Konfigurationscontainer:</p>\n<ul class=\"fig-list\"><li><code>MemAccGeneral: EcucParamConfContainerDef</code> (Multiplizität 1..1), aggregiert über <code>+parameter</code> fünf Konfigurationsparameter:\n<ul class=\"fig-list\"><li><code>MemAccMainFunctionPeriod: EcucFloatParamDef</code> (Multiplizität 1..1, <code>min = 0.0001</code>, <code>max = INF</code>)\n</li><li><code>MemAccDevErrorDetect: EcucBooleanParamDef</code> (Multiplizität 1..1)\n</li><li><code>MemAccCompareApi: EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>)\n</li><li><code>MemAcc64BitSupport: EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>)\n</li><li><code>MemAccPublicCddHeaderFile: EcucStringParamDef</code> (Multiplizität 0..*, <code>maxLength = 32</code>, <code>minLength = 1</code>)\n</li></ul>\n</li><li><code>MemAccAddressAreaConfiguration: EcucParamConfContainerDef</code> (Multiplizität 1..65535), aggregiert über <code>+subContainer</code>:\n<ul class=\"fig-list\"><li><code>MemAccSubAddressAreaConfiguration: EcucParamConfContainerDef</code> (Multiplizität 1..65536)\n</li></ul>\n</li><li><code>MemAccSynchronizationGroupConfiguration: EcucParamConfContainerDef</code> (Multiplizität 0..1), enthält:\n<ul class=\"fig-list\"><li><code>MemAccMSynchronizationGroupId: EcucIntegerParamDef</code> (Multiplizität 1..1, <code>min = 0</code>, <code>max = 65535</code>, <code>defaultValue = 0</code>) über <code>+parameter</code>\n</li><li><code>MemAccMSynchronizationSubAddressAreaRef: EcucReferenceDef</code> (Multiplizität 1..65535) über <code>+reference</code>, zielend (<code>+destination</code>) auf <code>MemAccSubAddressAreaConfiguration</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell stellt das Diagramm keine Laufzeitinteraktionen, Zustandsübergänge oder Aufrufsequenzen dar. Es definiert die Eingangsdaten für Generatoren zur Erzeugung von Konfigurationsheadern und Datenstrukturen zur Compile- bzw. Initialisierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Metamodellvorgabe für MemAcc-Generatoren und Konfigurationstools. <code>MemAccAddressAreaConfiguration</code> verlangt zwingend mindestens eine <code>MemAccSubAddressAreaConfiguration</code> (bis zu 65536 Subbereiche). <code>MemAccSynchronizationGroupConfiguration</code> ist optional (Multiplizität 0..1); falls konfiguriert, muss eine Synchronisations-Gruppen-ID vergeben werden und mindestens ein Verweis (<code>MemAccMSynchronizationSubAddressAreaRef</code>, bis zu 65535) auf einen bestehenden Subadressbereich existieren. Die Zykluszeit <code>MemAccMainFunctionPeriod</code> besitzt nach oben keine fixe Obergrenze mehr (<code>INF</code>), und der Parameter <code>MemAccUseMemFuncPtrTable</code> entfällt aus der Konfiguration.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9fcfc20666616b54", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des AUTOSAR-ECU-Konfigurationsmetamodells (BSW Module Description / EcucModuleDef) für das BSW-Modul <code>MemAcc</code> (Memory Access) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die statische Konfigurationsstruktur, Containerhierarchien und Parameterdefinitionen des Moduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Wurzelelement ist das Modul <code>MemAcc: EcucModuleDef</code> (Multiplizität 0..1). Es aggregiert über die Kompositionsrolle <code>+container</code> drei Konfigurationscontainer:</p>\n<ul class=\"fig-list\"><li><code>MemAccGeneral: EcucParamConfContainerDef</code> (Multiplizität 1..1), aggregiert über <code>+parameter</code> fünf Konfigurationsparameter:\n<ul class=\"fig-list\"><li><code>MemAccMainFunctionPeriod: EcucFloatParamDef</code> (Multiplizität 1..1, <code>min = 0.0001</code>, <code>max = INF</code>)\n</li><li><code>MemAccDevErrorDetect: EcucBooleanParamDef</code> (Multiplizität 1..1)\n</li><li><code>MemAccCompareApi: EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>)\n</li><li><code>MemAcc64BitSupport: EcucBooleanParamDef</code> (Multiplizität 1..1, <code>defaultValue = false</code>)\n</li><li><code>MemAccPublicCddHeaderFile: EcucStringParamDef</code> (Multiplizität 0..*, <code>maxLength = 32</code>, <code>minLength = 1</code>)\n</li></ul>\n</li><li><code>MemAccAddressAreaConfiguration: EcucParamConfContainerDef</code> (Multiplizität 1..65535), aggregiert über <code>+subContainer</code>:\n<ul class=\"fig-list\"><li><code>MemAccSubAddressAreaConfiguration: EcucParamConfContainerDef</code> (Multiplizität 1..65536)\n</li></ul>\n</li><li><code>MemAccSynchronizationGroupConfiguration: EcucParamConfContainerDef</code> (Multiplizität 0..1), enthält:\n<ul class=\"fig-list\"><li><code>MemAccMSynchronizationGroupId: EcucIntegerParamDef</code> (Multiplizität 1..1, <code>min = 0</code>, <code>max = 65535</code>, <code>defaultValue = 0</code>) über <code>+parameter</code>\n</li><li><code>MemAccMSynchronizationSubAddressAreaRef: EcucReferenceDef</code> (Multiplizität 1..65535) über <code>+reference</code>, zielend (<code>+destination</code>) auf <code>MemAccSubAddressAreaConfiguration</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell stellt das Diagramm keine Laufzeitinteraktionen, Zustandsübergänge oder Aufrufsequenzen dar. Es definiert die Eingangsdaten für Generatoren zur Erzeugung von Konfigurationsheadern und Datenstrukturen zur Compile- bzw. Initialisierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Metamodellvorgabe für MemAcc-Generatoren und Konfigurationstools. <code>MemAccAddressAreaConfiguration</code> verlangt zwingend mindestens eine <code>MemAccSubAddressAreaConfiguration</code> (bis zu 65536 Subbereiche). <code>MemAccSynchronizationGroupConfiguration</code> ist optional (Multiplizität 0..1); falls konfiguriert, muss eine Synchronisations-Gruppen-ID vergeben werden und mindestens ein Verweis (<code>MemAccMSynchronizationSubAddressAreaRef</code>, bis zu 65535) auf einen bestehenden Subadressbereich existieren. Die Zykluszeit <code>MemAccMainFunctionPeriod</code> besitzt nach oben keine fixe Obergrenze mehr (<code>INF</code>), und der Parameter <code>MemAccUseMemFuncPtrTable</code> entfällt aus der Konfiguration.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-063dba3365655ab2", "to": "FIG-7b29f334902e1f63", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Parameter <code>MemAccPublicCddHeaderFile</code> (<code>EcucStringParamDef</code>) zum Container <code>MemAccGeneral</code> hinzugefügt (<code>maxLength = 32</code>, <code>minLength = 1</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>).\n</li></ul>"}, {"from": "FIG-7b29f334902e1f63", "to": "FIG-4c58c90e60b01ed9", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Parameter <code>MemAccUseMemFuncPtrTable</code> aus <code>MemAccGeneral</code> entfernt.\n</li><li>Wertebereich des Parameters <code>MemAccMainFunctionPeriod</code>: <code>max</code> von <code>1.0</code> auf <code>INF</code> geändert.\n</li><li>Sub-Container <code>MemAccSubAddressAreaConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 1..65536) unter <code>MemAccAddressAreaConfiguration</code> hinzugefügt.\n</li><li>Container <code>MemAccSynchronizationGroupConfiguration</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..1) unter <code>MemAcc</code> hinzugefügt.\n</li><li>Parameter <code>MemAccMSynchronizationGroupId</code> (<code>EcucIntegerParamDef</code>, <code>min = 0</code>, <code>max = 65535</code>, <code>defaultValue = 0</code>, Multiplizität 1..1) zu <code>MemAccSynchronizationGroupConfiguration</code> hinzugefügt.\n</li><li>Referenz <code>MemAccMSynchronizationSubAddressAreaRef</code> (<code>EcucReferenceDef</code>, Multiplizität 1..65535) von <code>MemAccSynchronizationGroupConfiguration</code> mit Ziel (<code>+destination</code>) auf <code>MemAccSubAddressAreaConfiguration</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-4c58c90e60b01ed9", "to": "FIG-9fcfc20666616b54", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
